            ["C_Left"] = "reste {0}",
            ["C_Of"] = "{0} sur {1}",
            ["C_Usage"] = "MegaCopier — la copie qui survit aux coupures de courant\n\nUtilisation :\n  mcopy copy <source>... <dossier-destination> [options]\n  mcopy move <source>... <dossier-destination> [options]   Déplace (instantané sur le même disque)\n  mcopy send <source>... <dossier-destination> [--verify] [--move] [--also <autre-dossier>]... [--at HH:mm]\n                              Confie la copie à l'application MegaCopier (fenêtre et zone de notification)\n  mcopy send --test <sommes|dossier>...        Contrôle des fichiers de sommes dans l'application\n  mcopy send --delete [--secure] <chemin>...   Supprime (de façon sécurisée) depuis l'application\n  mcopy send --hash <dossier|fichiers>...      Crée un fichier de sommes dans l'application\n  mcopy send ... [--mirror|--update-only|--folders-only] [--dry-run]\n  mcopy test <sommes|dossier>...   Contrôle .sha256, .md5, .sfv, .xxh3... sans l'application\n  mcopy decrypt <chiffrés|dossier>... <dossier-destination>   Déchiffre des fichiers .mcenc\n  mcopy delete [--secure] --yes <chemin>...   Supprime sans l'application (--secure : écrase d'abord)\n  mcopy resume [id]      Reprend les tâches interrompues (ou une seule)\n  mcopy jobs             Liste les tâches en attente\n\nOptions de copy :\n  --verify               Relit la destination sans cache, compare les hachages et répare les blocs endommagés\n  --conflict <mode>      overwrite (par défaut) | skip | newer | rename | fail | ask\n  --limit-mb <n>         Limite la vitesse à n Mo/s\n  --force                Copie même si la destination est identique\n  --chunk-mb <n>         Tous les combien de Mo la progression est confirmée sur disque (64 par défaut)\n  --block-mb <n>         Taille de chaque lecture/écriture en Mo\n  --queue <n>            Lectures et écritures simultanées en vol\n  --no-unbuffered        Utilise le cache de Windows au lieu des E/S directes\n  --mirror               Synchronise : retire de la destination ce qui n'est plus dans la source\n  --update-only          Met à jour seulement les fichiers qui existent déjà dans la destination\n  --folders-only         Crée seulement la structure des dossiers\n  --dry-run              Simule : indique ce qui arriverait à chaque fichier sans rien changer\n  --versions <dossier>   Garde ce qui est remplacé ou retiré dans ce dossier de la destination\n  --skip-junk            Ignore Thumbs.db, desktop.ini, .DS_Store, ~$...\n  --smb-compress         Demande la compression SMB pour les copies réseau (réseaux lents)\n  --atomic               Tout ou rien : le dossier n'apparaît que lorsqu'il est complet\n  --rescue               Mode sauvetage : sauve ce qui est lisible d'un disque endommagé (l'illisible en zéros)\n  --delta                En remplaçant de gros fichiers, n'écrit que les blocs modifiés\n  --organize             Range photos et vidéos dans des dossiers année-mois selon la date de prise de vue\n  --skip-duplicates      Ne copie pas ce qui est déjà dans la destination (même contenu, n'importe quel nom)\n  --encrypt              Copie chiffrée par mot de passe (AES-256, fichiers .mcenc)\n  --backup             Mode sauvegarde : ignore les autorisations (console administrateur)\n  --crash-after-mb <n>   [test] Tue le processus après confirmation de n Mo d'un fichier\n\nCtrl+C met la copie en pause ; 'resume' reprend depuis le dernier bloc confirmé.",
