            ["C_Left"] = "залишилося {0}",
            ["C_Of"] = "{0} з {1}",
            ["C_Usage"] = "MegaCopier — копіювання, яке переживає вимкнення живлення\n\nВикористання:\n  mcopy copy <джерело>... <папка-призначення> [параметри]\n  mcopy move <джерело>... <папка-призначення> [параметри]   Переміщує (миттєво на тому самому диску)\n  mcopy send <джерело>... <папка-призначення> [--verify] [--move] [--also <інша-папка>]... [--at HH:mm]\n                              Передає копіювання застосунку MegaCopier (вікно й область сповіщень)\n  mcopy send --test <суми|папка>...            Перевіряє файли сум у застосунку\n  mcopy send --delete [--secure] <шлях>...     Видаляє (безповоротно) через застосунок\n  mcopy send --hash <папка|файли>...           Створює файл сум у застосунку\n  mcopy send ... [--mirror|--update-only|--folders-only] [--dry-run]\n  mcopy test <суми|папка>...   Перевіряє .sha256, .md5, .sfv, .xxh3... без застосунку\n  mcopy decrypt <зашифровані|папка>... <папка-призначення>   Розшифровує файли .mcenc\n  mcopy delete [--secure] --yes <шлях>...   Видаляє без застосунку (--secure: спершу перезаписує)\n  mcopy resume [id]      Продовжує перервані завдання (або одне)\n  mcopy jobs             Список завдань, що очікують\n\nПараметри copy:\n  --verify               Перечитує призначення без кешу, порівнює геші й виправляє пошкоджені блоки\n  --conflict <режим>     overwrite (за замовчуванням) | skip | newer | rename | fail | ask\n  --limit-mb <n>         Обмежує швидкість до n МБ/с\n  --force                Копіює, навіть якщо призначення збігається\n  --chunk-mb <n>         Через скільки МБ підтверджується запис на диск (за замовчуванням 64)\n  --block-mb <n>         Розмір кожного читання/запису в МБ\n  --queue <n>            Одночасні операції читання й запису\n  --no-unbuffered        Використовує кеш Windows замість прямого введення-виведення\n  --mirror               Синхронізує: видаляє з призначення те, чого більше немає в джерелі\n  --update-only          Оновлює лише файли, які вже є в призначенні\n  --folders-only         Створює лише структуру папок\n  --dry-run              Моделює: повідомляє, що буде з кожним файлом, нічого не змінюючи\n  --versions <папка>     Зберігає замінене чи видалене в цій папці призначення\n  --skip-junk            Пропускає Thumbs.db, desktop.ini, .DS_Store, ~$...\n  --smb-compress         Запитує стиснення SMB під час копіювання мережею (повільні мережі)\n  --atomic               Все або нічого: папка з'являється, лише коли вона повна\n  --rescue               Режим порятунку: рятує читабельне з пошкодженого диска (нечитабельне — нулями)\n  --delta                Під час заміни великих файлів записує лише змінені блоки\n  --organize             Розкладає фото й відео по папках рік-місяць за датою зйомки\n  --skip-duplicates      Не копіює те, що вже є в призначенні (той самий вміст, будь-яке ім'я)\n  --encrypt              Копія, зашифрована паролем (AES-256, файли .mcenc)\n  --backup             Режим резервного копіювання: в обхід дозволів (консоль адміністратора)\n  --crash-after-mb <n>   [тест] Завершує процес після підтвердження n МБ файлу\n\nCtrl+C призупиняє копіювання; 'resume' продовжує з останнього підтвердженого блоку.",
